package com.guocheng.mediapocket;
import android.animation.*;import android.graphics.drawable.GradientDrawable;import android.text.TextUtils;import android.view.*;import android.view.animation.DecelerateInterpolator;import android.widget.*;import org.json.*;
/** Image pages follow the finger; fixed captions crossfade and the full-screen backdrop blends independently. */
final class HeroSwipe implements View.OnTouchListener {
 final ScrapedMainActivity a;final FrameLayout host,page;FrameLayout previous,next;LinearLayout previousText,nextText;final int slop,minVelocity,maxVelocity;VelocityTracker velocity;ValueAnimator animator;
 float downX,downY,startOffset,offset;boolean tracking,dragging,disposed;int pointer=-1;int animationToken;
 HeroSwipe(ScrapedMainActivity a,FrameLayout host,FrameLayout page){this.a=a;this.host=host;this.page=page;ViewConfiguration config=ViewConfiguration.get(a);slop=config.getScaledTouchSlop();minVelocity=Math.max(config.getScaledMinimumFlingVelocity(),a.dp(400));maxVelocity=config.getScaledMaximumFlingVelocity();host.setClipChildren(true);host.setOnTouchListener(this);}
 boolean busy(){return tracking||animator!=null;}
 boolean active(){return !disposed&&a.homeCanvas&&a.hero==host&&!a.isFinishing();}
 void stopTimer(){a.carousel.removeCallbacks(a.tick);}
 void resumeTimer(){stopTimer();if(active()&&a.resumed&&a.heroes.length()>1)a.carousel.postDelayed(a.tick,7000);}
 void front(){host.bringChildToFront(page);if(a.heroShadeView!=null)host.bringChildToFront(a.heroShadeView);host.bringChildToFront(a.heroInfo);if(previousText!=null)host.bringChildToFront(previousText);if(nextText!=null)host.bringChildToFront(nextText);}
 void refresh(){if(disposed)return;cancel();removeNeighbors();if(a.heroes.length()<2)return;install(false,CarouselRules.index(a.heroIndex,-1,a.heroes.length()));install(true,CarouselRules.index(a.heroIndex,1,a.heroes.length()));front();place(0);}
 void install(boolean forward,int index){FrameLayout image=forward?next:previous;LinearLayout text=forward?nextText:previousText;if(image!=null)host.removeView(image);if(text!=null)host.removeView(text);JSONObject m=metadata(index);image=picture(m);text=caption(m,index);text.setAlpha(0);host.addView(image,new FrameLayout.LayoutParams(-1,-1));host.addView(text,new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM));if(forward){next=image;nextText=text;}else{previous=image;previousText=text;}}
 void removeNeighbors(){for(View v:new View[]{previous,next,previousText,nextText})if(v!=null)host.removeView(v);previous=next=null;previousText=nextText=null;}
 JSONObject metadata(int index){JSONObject m=a.heroes.optJSONObject(index);if(m==null)m=new JSONObject();try{JSONObject cached=new JSONObject(a.prefs.getString("cinema.meta."+m.optString("type",a.heroType)+"."+m.optString("id"),""));if(DetailMetadata.useful(cached))m=DetailMetadata.merge(m,cached);}catch(Exception ignored){}return m;}
 FrameLayout picture(JSONObject m){FrameLayout slide=new FrameLayout(a);slide.setBackgroundColor(a.surface());ImageView image=new ImageView(a);image.setScaleType(ImageView.ScaleType.CENTER_CROP);slide.addView(image,new FrameLayout.LayoutParams(-1,-1));String art=m.optString("background");if(art.isEmpty())art=m.optString("poster");TvPosterImages.load(a,image,art,a.getResources().getDisplayMetrics().widthPixels);return slide;}
 LinearLayout caption(JSONObject m,int index){LinearLayout info=new LinearLayout(a);info.setOrientation(1);info.setGravity(Gravity.CENTER);info.setPadding(a.dp(24),0,a.dp(24),a.dp(14));String logo=m.optString("logo");if(!logo.isEmpty()){ImageView mark=new ImageView(a);mark.setScaleType(ImageView.ScaleType.FIT_CENTER);TvPosterImages.load(a,mark,logo,a.dp(320));info.addView(mark,new LinearLayout.LayoutParams(a.dp(270),a.dp(76)));}
  TextView title=a.text(m.optString("name","影片"),logo.isEmpty()?26:16,a.light?a.ink():0xffffffff);title.setGravity(Gravity.CENTER);title.setTypeface(null,1);title.setMaxLines(2);title.setEllipsize(TextUtils.TruncateAt.END);info.addView(title);
  TextView facts=a.text(HomeRules.heroFacts(m),11,a.light?a.muted():0xffe0edf0);facts.setGravity(Gravity.CENTER);info.addView(facts);TextView description=a.text(HomeRules.heroDescription(m),11,a.light?a.muted():0xffd6e8eb);description.setGravity(Gravity.CENTER);description.setLines(2);description.setEllipsize(TextUtils.TruncateAt.END);description.setLineSpacing(a.dp(2),1);info.addView(description);
  LinearLayout dots=new LinearLayout(a);dots.setGravity(Gravity.CENTER);dots.setPadding(0,a.dp(10),0,0);for(int i=0;i<a.heroes.length();i++){View dot=new View(a);dot.setBackground(a.rounded(i==index?0xffc0e1f5:0x7099b4be,4));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(a.dp(i==index?17:5),a.dp(5));p.setMargins(a.dp(3),0,a.dp(3),0);dots.addView(dot,p);}info.addView(dots);return info;
 }
 ImageView image(FrameLayout frame){return frame!=null&&frame.getChildCount()>0&&frame.getChildAt(0) instanceof ImageView?(ImageView)frame.getChildAt(0):null;}
 void place(float value){offset=value;int width=host.getWidth();float progress=SceneRules.progress(value,width),fade=SceneRules.fade(progress);page.setTranslationX(value);if(previous!=null)previous.setTranslationX(value-width);if(next!=null)next.setTranslationX(value+width);a.heroInfo.setTranslationX(0);a.heroInfo.setAlpha(1-fade);if(previousText!=null){previousText.setTranslationX(0);previousText.setAlpha(value>0?fade:0);}if(nextText!=null){nextText.setTranslationX(0);nextText.setAlpha(value<0?fade:0);}if(a.homeAtmosphere!=null)a.homeAtmosphere.blend(a.heroImage,value<0?image(next):value>0?image(previous):null,progress);}
 void interruptAnimation(){animationToken++;if(animator!=null){animator.cancel();animator=null;}}
 void layer(int type){for(View v:new View[]{page,previous,next,a.heroInfo,previousText,nextText})if(v!=null)v.setLayerType(type,null);}
 void cancel(){interruptAnimation();tracking=dragging=false;pointer=-1;recycle();place(0);layer(View.LAYER_TYPE_NONE);if(host.getParent()!=null)host.getParent().requestDisallowInterceptTouchEvent(false);}
 void dispose(){cancel();disposed=true;removeNeighbors();host.setOnTouchListener(null);}
 void recycle(){if(velocity!=null){velocity.recycle();velocity=null;}}
 @Override public boolean onTouch(View view,MotionEvent event){if(!active())return false;int action=event.getActionMasked();
  if(action==MotionEvent.ACTION_DOWN){interruptAnimation();stopTimer();tracking=true;dragging=Math.abs(offset)>slop;startOffset=offset;downX=event.getX();downY=event.getY();pointer=event.getPointerId(0);recycle();velocity=VelocityTracker.obtain();velocity.addMovement(event);if(dragging&&host.getParent()!=null)host.getParent().requestDisallowInterceptTouchEvent(true);return true;}
  if(!tracking)return false;if(velocity!=null)velocity.addMovement(event);
  if(action==MotionEvent.ACTION_POINTER_DOWN||action==MotionEvent.ACTION_CANCEL){tracking=dragging=false;pointer=-1;recycle();settle(0,0);return true;}
  int at=event.findPointerIndex(pointer);if(at<0){cancel();resumeTimer();return true;}float x=event.getX(at)-downX,y=event.getY(at)-downY;
  if(action==MotionEvent.ACTION_MOVE){if(!dragging){if(Math.abs(y)>slop&&!CarouselRules.horizontal(x,y,slop)){tracking=false;recycle();if(host.getParent()!=null)host.getParent().requestDisallowInterceptTouchEvent(false);resumeTimer();return false;}if(a.heroes.length()<2||!CarouselRules.horizontal(x,y,slop))return true;dragging=true;layer(View.LAYER_TYPE_HARDWARE);if(host.getParent()!=null)host.getParent().requestDisallowInterceptTouchEvent(true);}
   int width=host.getWidth();place(Math.max(-width,Math.min(width,startOffset+x)));return true;}
  if(action==MotionEvent.ACTION_UP){float speed=0;if(velocity!=null){velocity.computeCurrentVelocity(1000,maxVelocity);speed=velocity.getXVelocity(pointer);}boolean moved=dragging;tracking=dragging=false;pointer=-1;recycle();if(host.getParent()!=null)host.getParent().requestDisallowInterceptTouchEvent(false);if(moved){settle(CarouselRules.target(offset,speed,host.getWidth(),minVelocity),speed);}else{place(0);resumeTimer();host.performClick();}return true;}return true;
 }
 void advance(int step){if(!active()||a.heroes.length()<2||step==0)return;if(tracking||animator!=null)return;stopTimer();int target=CarouselRules.index(a.heroIndex,step,a.heroes.length());if(target==a.heroIndex){resumeTimer();return;}install(step>0,target);front();place(0);settle(step,0);}
 void settle(int step,float speed){if(!active()){cancel();return;}int width=host.getWidth();if(width<=0){cancel();resumeTimer();return;}float destination=step==0?0:step>0?-width:width;interruptAnimation();int token=++animationToken;layer(View.LAYER_TYPE_HARDWARE);animator=ValueAnimator.ofFloat(offset,destination);animator.setDuration(CarouselRules.duration(offset,destination,width,speed));animator.setInterpolator(new DecelerateInterpolator(1.8f));animator.addUpdateListener(animation->{if(token==animationToken&&active())place((Float)animation.getAnimatedValue());});animator.addListener(new AnimatorListenerAdapter(){@Override public void onAnimationEnd(Animator animation){if(token!=animationToken)return;animator=null;layer(View.LAYER_TYPE_NONE);place(0);if(active()&&step!=0)a.commitHero(step);resumeTimer();}});animator.start();}
}
